sys_script_fix.script:
var eventId = 'EVT0001010'; // Replace with your Event sys_id

var feedbackGR = new GlideRecord('x_1790229_event_ma_feedback'); // Replace with your actual Feedback table
feedbackGR.addQuery('u_event_id.number', eventId); // Assuming 'u_event' is the reference field to Event
feedbackGR.query();

while (feedbackGR.next()) {
    gs.info('Feedback Id: ' + feedbackGR.getDisplayValue('number'));       // User who gave the feedback
    gs.info('Rating: ' + feedbackGR.getValue('u_rating'));                 // e.g., numeric or choice field
    gs.info('Comments: ' + feedbackGR.getValue('u_comments'));

}
